/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓

    ▓              🌟  KuKo Day 478  🌟 

    ▓ Image tab: color and helpers, u can also see the 
    ▓ length of smell and the angles 

    ▓ Buffer A: State setup of the agents

    ▓ Buffer B: Diffusion, trail update of the agents 

    ▓ I got the idea from @michael0884 on his Physarum Circular shader 
    ▓ https://www.shadertoy.com/view/wtKGW1

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

float so(float d) {return smoothstep(1.,0.,d);}

void mainImage( out vec4 O, in vec2 I )
{
    vec3 v = T(iChannel0, I).rgb;
    v /= (0.2+v);

    vec3 col = v + v*v;

    // some helpers to visualize the smell of the turns 
    // uncomment to see the angles and the head 
    /*
    for(int i=0; i<N; i++)
    {
        vec4 a = T(iChannel1, vec2(i,0));
        vec2 p = loop_d(I - a.xy),
        // the head
        hd = SD*vec2(cos(a.z),sin(a.z)),
        l  = SD*vec2(cos(a.z+SA),sin(a.z+SA)),
        r  = SD*vec2(cos(a.z-SA),sin(a.z-SA));

        float d1 = line(p, vec2(0), hd),
        d2 = line(p, vec2(0), l) - .5,
        d3 = line(p, vec2(0), r) - .5;

        vec3 bgCol = .5+.5*cos(float(i) * 0.2 + vec3(0,2,3)) * 0.7;

        col = mix(col, vec3(0.6), so(d1) *0.7);
        col = mix(col, bgCol, so(d2) *0.8);
        col = mix(col, bgCol, so(d3) *0.8);
    }
    */

    O = vec4(col,1);
}

#define R iResolution.xy
#define t iTime
#define N 100

// textures
#define px(a, p) texture(a, vec2(p)/R)
#define T(a, p) texelFetch(a, ivec2(p -0.5),0)
// gaussian
#define G(x,r) exp(-dot(x,x)/r/r)      

// space cycle
#define loop(p) mod(p, R)
#define loop_d(p) mod(p + R*.5, R) - R*.5

// HEAD and ANGLE, SPEED
// Change the length of the head or the angle 
const float SD = -20., SA = 1., SPEED = 1.;

// TRAIL this will affect the turn as well 
const float TRAIL = 0.01023;

//functions
float h1(vec2 p)
{
	vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 H2(vec2 p)
{
	vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx+33.33);
    return fract((p3.xx+p3.yz)*p3.zy);
}

vec4 laplace(sampler2D ch, vec2 p)
{
    vec3 v = vec3(2,0,-2);
    return T(ch, p+v.xy) + T(ch, p+v.zy)
         + T(ch, p+v.yx) + T(ch, p+v.yz)-(4.*T(ch, p));
}

float line(vec2 p, vec2 a, vec2 b)
{
    vec2 pa = a-p, ab = b-a;
    float h = clamp(dot(pa,ab)/dot(ab,ab), 0.,1.);
    return length(pa - ab*h) ;
}

/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓

    ▓              🌟  State of the agents  🌟 

    ▓ Buffer A: Setup the state, random position, left, 
    ▓ right turn and speed 

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/


void mainImage( out vec4 O, in vec2 I )
{
    // load my own buffer and read all potential agents
    O = T(iChannel0, I);

    // which agent am I from my column 
    float id = floor(I.x);

    // only the first row and first N columns hold real agents 
    bool me = (I.y < 1.) && (id < float(N));

    if(me)
    {
        // how far my feelers reach and the angle the splay off my heading
        // setup a Left and Right feeler we look sd ahead + sa
        float l = px(iChannel1, loop(O.xy + SD*vec2(cos(O.z+SA),sin(O.z+SA)))).w;
        float r = px(iChannel1, loop(O.xy + SD*vec2(cos(O.z-SA),sin(O.z-SA)))).w;

        // Steer, left and right are the gradients
        O.z += .65*tanh(5.*(l-r));

        // move step 2px along the new heading 
        O.xy = loop(O.xy + SPEED*vec2(cos(O.z), sin(O.z)));
    }
    // not an agent stay empty
    else O = vec4(0);

    // at frame 0 scatter agents at random positions 
    if(iFrame < 1)
        if(me)
        {
            O.xy = R * H2(vec2(id,1));     // random position 
            O.z = 6.2831 * h1(vec2(id,1)); // random heading
            O.w = 0.;

        } else O = vec4(0);            
}

/*
    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓

    ▓              🌟  Update the agents  🌟 

    ▓ Buffer B: Diffusion, trail, read the particles  

    ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓
*/

void mainImage( out vec4 O, in vec2 I )
{
    // we read our current texture, so we load who was our last frame
    O = T(iChannel1, I);

    // diffuse with laplace
    O += 0.25 * laplace(iChannel1, I);

    // decay with with the output 
    O -= TRAIL * O;

    // deposite: read every agent and if one is near, add a bump 
    //float dep = 0.;
    vec3 dep = vec3(0);
    float smell = 0.0;
    for(int i=0; i<N; i++)
    {
        // agent i lives at (i,0) on every other buffer
        vec4 a = T(iChannel0, vec2(i,0));

        // set up some color according to the particle i
        vec3 col = .5+.5*cos(float(i) * 0.015 + vec3(3,2,1) + t*.5);

        // how close am I to agent i: loop wraps the distance around
        // deposite the spheres
        float w = G(loop_d(I-a.xy), 2.0);
        dep += (w) * col;
        smell += w;
    }

    // fold the fresh trail at half the strength 
    //O += .5 * dep;
    O.xyz += .5 * dep;
    O.w += .5 * smell;
    // safety net to prevent blow up 
    O = clamp(O, vec4(0), vec4(60));
    //O.xyz = clamp(O.xyz, vec3(0), vec3(60));

    if(iFrame < 1) O = vec4(0);
}
